import { getMatchCount } from '@/api/safeDanger/control/statistics';
export default {
  data: function data() {
    return {
      chartData: 0,
      loading: false
    };
  },
  mounted: function mounted() {
    this.getDetail();
  },
  methods: {
    getDetail: function getDetail() {
      var _this = this;
      this.loading = true;
      this.chartData = 0;
      getMatchCount().then(function (res) {
        _this.loading = false;
        _this.chartData = res.data.toFixed(0);
        if (_this.chartData > 0) {
          _this.$nextTick(function () {
            _this.initChart();
          });
        }
      }).catch(function (err) {
        _this.loading = false;
      });
    },
    initChart: function initChart() {
      var areaChart = this.$echarts.init(document.getElementById('officeMatch'));
      areaChart.setOption({
        tooltip: {
          formatter: '{a}: {b}'
        },
        // zoom: 10,
        series: [{
          type: 'gauge',
          data: [{
            value: this.chartData
          }],
          radius: '87%',
          detail: {
            fontSize: 25,
            formatter: '{value}%'
          },
          axisLine: {
            lineStyle: {
              width: 20,
              color: [[0.3, "#fd666d"], [0.7, "#37a2da"], [1, "#67e0e3"]]
            }
          },
          pointer: {
            length: 100,
            width: 5
          }
        }]
      });
    }
  }
};
